          min:40,
          max:50,
        },
        {
          min:50,
          max:60,
        }
        ]).numericFacetFilters('discounted_price',20000,49999);
        this.data = await searchClient.search("saree","KSNQ58MRXELY5JCX767TDSA1");
        this.result=this.data.results;
        this.textFilterFields=this.data.textFacets;
        console.log(this.textFilterFields);
        this.numericFilterFields=this.data.numericFacets;
        console.log(this.numericFilterFields);
        for (const element of this.result) {
          console.log(element.title.split(" ").slice(0,2).join(" ")+" "+element.product_type+" "+element.price+" "+element.discounted_price+" "+element.discount+" "+element.images[0].src+" "+element.reviews_average+" "+element.reviews_count+" "+element.created_at+" "+element.isActive);
        }
      },
      sortByWho(element:string):void{
        switch (element) {
            case "Price: Low to High":
              this.sortBy='discounted_price';
              break;
            case "Price: High to Low":
              this.sortBy='-discounted_price';
              break;
            case "Discount: High to Low":
              this.sortBy='-discount';
              break;
            case "Date: Old to New":
              this.sortBy="created_at";
              break;
            case "Date: New to Old":
              this.sortBy="-created_at";
              break;
            default:
              break;
          }
          console.log(this.sortBy);
          this.fetchData();
      },
      toggle(id:string):void{
        this.visibleStates[id]=!this.visibleStates[id];
      },
      heading(label:string):string{
        switch (label) {
          case "discounted_price":
            return "Price";
            break;
          case "discount":
            return "Discount";
            break;
          case "product_type":
            return "Category";
            break;
          case "st_blousetype":
            return "Blouse Piece";
            break;
          case "st_occasion":
            return "Occasion";
            break;
          case "st_technique":
            return "Technique"
            break;
          case "st_pattern":
            return "Pattern"
            break;
          default:
            return label.charAt(0)?.toUpperCase()+label.slice(1);
            break;
        }
      },
      display():void{
        console.log(this.selectedFilters);
      },
      isRangeSelected(selectedArray:any[], min:number, max:number) {
    return selectedArray.some(range => range[0] === min && range[1] === max);
    },  
    toggleRange(selectedArray:any[],min:number,max:number){
      const index = selectedArray.findIndex(range => range[0] === min && range[1] === max);
      if (index === -1) {
      selectedArray.push([min, max]);
    } else {
      selectedArray.splice(index, 1);
    }
    }
  
    },
    mounted(){
      this.fetchData();
    },
    watch:{
      filters:{
        handler(){
          this.selectedFilters=this.filters.filter((ele)=>{
            return ele.selected.length>0;
          });
          this.display()
        },
        deep:true
      }
    }
  })
</script>

